function Repair-ProUpgradeFixture($Session,[string]$CaseId){
 return Invoke-Command -Session $Session -ArgumentList $CaseId -ScriptBlock {
  param($caseId)
  $ErrorActionPreference='Stop';$file='C:\MuLab\approved\upgrade-'+$caseId+'-config.json';$config=[IO.File]::ReadAllText($file)|ConvertFrom-Json;$failedFile='C:\MuLab\approved\upgrade-'+$caseId+'-cleanup-result.json';$failed=[IO.File]::ReadAllText($failedFile)|ConvertFrom-Json;$stateFile=Join-Path $config.directory 'state.json';$state=[IO.File]::ReadAllText($stateFile)|ConvertFrom-Json
  if($caseId -notmatch '^[a-f0-9]{32}$' -or $config.caseId -ne $caseId -or $config.directory -ne ('C:\MuLab\public\upgrade-'+$caseId) -or $config.cleanupRetry -or $failed.caseId -ne $caseId -or $failed.complete -ne $false -or -not $failed.processExitConfirmed -or -not $failed.brokerExitConfirmed -or @($failed.checks).Count -ne 3 -or @($failed.checks|Where-Object passed -ne $true).Count -or $failed.error.message -notlike '*Cannot pin metadata directory*' -or $failed.after.registered -ne 1 -or $failed.after.diskGiB -ne 40 -or $state.diskGiB -ne 40 -or (Get-LocalUser $config.userName).SID.Value -ne $config.userSid){throw 'Only the exact terminal cleanup permission failure admits fixture repair'}
  if(@(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -and ($_.ExecutablePath -eq $config.launcher -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe' -or $_.CommandLine -like ('*'+$caseId+'*'))}).Count){throw 'A case actor remains live'}
  $ownerRoot=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$config.userSid);$primary=Join-Path $ownerRoot 'vms.json';$ledger=[IO.File]::ReadAllText($primary)|ConvertFrom-Json;$vm=@(Get-VM);$record=$ledger.records.($state.environmentId)
  if($ledger.version -ne 2 -or $ledger.ownerSid -ne $config.userSid -or @($ledger.records.psobject.Properties).Count -ne 1 -or (Get-FileHash $primary).Hash -ne (Get-FileHash (Join-Path $ownerRoot 'vms.backup.json')).Hash -or $vm.Count -ne 1 -or [string]$vm[0].Id -ne $state.platformId -or [string]$vm[0].State -ne 'Off' -or $record.platformId -ne $state.platformId -or $record.ownerSid -ne $config.userSid -or $record.diskGrowth){throw 'Original stopped allocation must remain intact before fixture repair'}
  $disk=Join-Path $ownerRoot ('vms/'+$state.environmentId+'/disk.vhdx');$drives=@(Get-VMHardDiskDrive -VM $vm[0]);$vhd=Get-VHD -Path $disk
  if($drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -ne [IO.Path]::GetFullPath($disk) -or [long]$vhd.Size -ne 40GB -or ([guid]$vhd.DiskIdentifier).ToString('D') -ne $failed.after.diskIdentifier -or $vhd.ParentPath -or @(Get-VMSnapshot -VM $vm[0]).Count){throw 'Original disk boundary changed'}
  $beforeDisk=(Get-FileHash $disk).Hash;$data=Join-Path $config.directory 'app-data';foreach($entry in $state.dataHashes.psobject.Properties){if($entry.Name -ne 'state.sqlite' -and (Get-FileHash (Join-Path $data $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Original encrypted/user bytes changed'}}
  $parent='C:\MuLab\public';$acl=Get-Acl -LiteralPath $parent;$sid=[Security.Principal.SecurityIdentifier]::new($config.userSid);$oldSddl=$acl.Sddl
  if((Get-Item -LiteralPath $parent).Attributes -band [IO.FileAttributes]::ReparsePoint -or @($acl.Access|Where-Object {$_.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value -eq $config.userSid}).Count){throw 'Unexpected fixture parent ACL preserved'}
  $history='C:\MuLab\private\upgrade-'+$caseId+'-cleanup-history-'+[guid]::NewGuid().ToString('N');[IO.Directory]::CreateDirectory($history)|Out-Null;[IO.File]::Copy($failedFile,(Join-Path $history 'approved-failed-result.json'));[IO.File]::Copy($stateFile,(Join-Path $history 'original-state.json'))
  $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid,([Security.AccessControl.FileSystemRights]::ListDirectory -bor [Security.AccessControl.FileSystemRights]::ReadAttributes),[Security.AccessControl.InheritanceFlags]::None,[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow));Set-Acl -LiteralPath $parent -AclObject $acl
  if((Get-FileHash $disk).Hash -ne $beforeDisk){throw 'Fixture ACL repair changed disk bytes'}
  foreach($artifact in @(Get-ChildItem -LiteralPath $config.directory -Filter 'cleanup-*' -File)){$from=[IO.Path]::GetFullPath($artifact.FullName);$to=[IO.Path]::GetFullPath((Join-Path $history $artifact.Name));if([IO.Path]::GetDirectoryName($from) -ne $config.directory -or [IO.Path]::GetDirectoryName($to) -ne $history){throw 'Failure archival escaped fixed case/history directories'};[IO.File]::Move($from,$to)}
  $state.dataHashes.'state.sqlite'=(Get-FileHash (Join-Path $data 'state.sqlite')).Hash.ToLowerInvariant();[IO.File]::WriteAllText($stateFile,($state|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false))
  $receipt=@{complete=$true;caseId=$caseId;scope='fixture-parent-list-and-attribute-access-only';directory=$parent;rights=129;inherits=$false;originalDiskUnchanged=$true;failedProcessesExited=$true;sqliteRebaselinedAfterConfirmedClosedBackend=$true;encryptedBytesUnchanged=$true;history=$history;oldSddl=$oldSddl;newSddl=(Get-Acl $parent).Sddl;failedResultSha256=(Get-FileHash (Join-Path $history 'approved-failed-result.json')).Hash.ToLowerInvariant()}
  $config|Add-Member -NotePropertyName cleanupRetry -NotePropertyValue $receipt;[IO.File]::WriteAllText($file,($config|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText(('C:\MuLab\approved\upgrade-'+$caseId+'-fixture-repair.json'),($receipt|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));return $receipt
 }
}
